function shell() {
    return createObject("WScript.Shell");
}
function dateArg(v) {
    return cdate(v).parts();
}
function intervalAdd(interval, n, d) {
    const p = cdate(d).parts();
    const [y, m, day, h, mi, s] = [p.getUTCFullYear(), p.getUTCMonth() + 1, p.getUTCDate(), p.getUTCHours(), p.getUTCMinutes(), p.getUTCSeconds()];
    n = Math.trunc(n);
    const clampDay = (yy, mm) => {
        const t = new Date(Date.UTC(2000, mm, 0));
        t.setUTCFullYear(yy, mm, 0);
        return Math.min(day, t.getUTCDate());
    };
    return inDateRange(intervalAddParts(interval, n, y, m, day, h, mi, s, clampDay), "DateAdd");
}
function intervalAddParts(interval, n, y, m, day, h, mi, s, clampDay) {
    switch (String(interval).toLowerCase()) {
        case "yyyy":
            return dateOf(y + n, m, clampDay(y + n, m), h, mi, s);
        case "q":
        case "m": {
            const total = y * 12 + (m - 1) + (interval.toLowerCase() === "q" ? n * 3 : n);
            const yy = Math.floor(total / 12);
            const mm = (total % 12) + 1;
            return dateOf(yy, mm, clampDay(yy, mm), h, mi, s);
        }
        case "d":
        case "y":
        case "w":
            return dateOf(y, m, day + n, h, mi, s);
        case "ww":
            return dateOf(y, m, day + n * 7, h, mi, s);
        case "h":
            return dateOf(y, m, day, h + n, mi, s);
        case "n":
            return dateOf(y, m, day, h, mi + n, s);
        case "s":
            return dateOf(y, m, day, h, mi, s + n);
        default:
            return raise(5, interval);
    }
}
function intervalDiff(interval, d1, d2) {
    const a = dateArg(d1);
    const b = dateArg(d2);
    const days = Math.floor(oaToLinear(cdate(d2).oa)) - Math.floor(oaToLinear(cdate(d1).oa));
    switch (String(interval).toLowerCase()) {
        case "yyyy":
            return b.getUTCFullYear() - a.getUTCFullYear();
        case "q":
            return (b.getUTCFullYear() - a.getUTCFullYear()) * 4 + Math.floor(b.getUTCMonth() / 3) - Math.floor(a.getUTCMonth() / 3);
        case "m":
            return (b.getUTCFullYear() - a.getUTCFullYear()) * 12 + b.getUTCMonth() - a.getUTCMonth();
        case "d":
        case "y":
            return days;
        case "w":
            return Math.trunc(days / 7);
        case "h":
            return Math.trunc((b - a) / 3600000);
        case "n":
            return Math.trunc((b - a) / 60000);
        case "s":
            return Math.trunc((b - a) / 1000);
        default:
            return raise(5, interval);
    }
}

/** `Format` for the common numeric and date patterns; anything else is formatted by Excel (`TEXT`). */
function format(value, pattern) {
    if (pattern === undefined || pattern === "") return cstr(value);
    const p = String(pattern);
    const isDate = value instanceof RDate || (typeof value === "string" && /[/:-]/.test(value) && /[ymdhns]/i.test(p));
    if (isDate && /^[ymdhnsYMDHNS/\-:. 年月日時分秒]+$/.test(p)) {
        const d = dateArg(value);
        const p2 = (n) => String(n).padStart(2, "0");
        const fields = {
            yyyy: String(d.getUTCFullYear()), yy: p2(d.getUTCFullYear() % 100),
            mm: p2(d.getUTCMonth() + 1), m: String(d.getUTCMonth() + 1),
            dd: p2(d.getUTCDate()), d: String(d.getUTCDate()),
            hh: p2(d.getUTCHours()), h: String(d.getUTCHours()),
            nn: p2(d.getUTCMinutes()), n: String(d.getUTCMinutes()),
            ss: p2(d.getUTCSeconds()), s: String(d.getUTCSeconds()),
        };
        return p.replace(/yyyy|yy|mm|m|dd|d|hh|h|nn|n|ss|s/gi, (t) => fields[t.toLowerCase()]);
    }
    const num = /^(#,##)?(0+)(?:\.(0+))?(%)?$/.exec(p);
    if (num && !isDate) {
        let x = cnum(value) * (num[4] ? 100 : 1);
        const decimals = num[3] ? num[3].length : 0;
        x = round(x, decimals);
        let [int, frac] = Math.abs(x).toFixed(decimals).split(".");
        int = int.padStart(num[2].length, "0");
        if (num[1]) int = int.replace(/\B(?=(\d{3})+$)/g, ",");
        return (x < 0 ? "-" : "") + int + (frac ? `.${frac}` : "") + (num[4] || "");
    }
    if (com !== null || mock || stand() !== null) return call(get(application(), "WorksheetFunction"), "Text", [value, p]);
    return unsupported(`Format(…, "${p}")`);
}

const WIDE_OFFSET = 0xfee0;
function strConv(s, mode) {
    let out = cstr(s);
    if (mode & 1) out = out.toUpperCase();
    if (mode & 2) out = out.toLowerCase();
    if ((mode & 3) === 3) out = cstr(s).toLowerCase().replace(/(^|\s)(\S)/g, (_, a, b) => a + b.toUpperCase());
    if (mode & 4) out = out.replace(/[!-~]/g, (c) => String.fromCharCode(c.charCodeAt(0) + WIDE_OFFSET)).replace(/ /g, "　");
    if (mode & 8) out = out.replace(/[！-～]/g, (c) => String.fromCharCode(c.charCodeAt(0) - WIDE_OFFSET)).replace(/　/g, " ");
    if (mode & 16) out = out.replace(/[ぁ-ゖ]/g, (c) => String.fromCharCode(c.charCodeAt(0) + 0x60));
    if (mode & 32) out = out.replace(/[ァ-ヶ]/g, (c) => String.fromCharCode(c.charCodeAt(0) - 0x60));
    if (mode & (64 | 128)) unsupported("StrConv(vbUnicode / vbFromUnicode)");
    return out;
}

